// Legacy editorial assessment builder; includes network checks. The current
// local-only report is generated by build-local-seo-score-report.mjs.
import fs from 'node:fs/promises';
import {existsSync} from 'node:fs';
import {JSDOM} from 'jsdom';
import {routes,routeInfo,metadata} from '../src/catalog.js';

const reportDate=process.argv.find(x=>x.startsWith('--date='))?.slice(7)||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
if(!/^\d{4}-\d{2}-\d{2}$/.test(reportDate)||new Date(reportDate+'T00:00:00Z').toISOString().slice(0,10)!==reportDate)throw Error('Use --date=YYYY-MM-DD for the report date.');
const displayDate=new Intl.DateTimeFormat('en-GB',{timeZone:'UTC',day:'numeric',month:'long',year:'numeric'}).format(new Date(reportDate+'T00:00:00Z'));

const baseline=JSON.parse(await fs.readFile('design/seo-audit-2026-10-20/pages.json','utf8'));
const verification=JSON.parse(await fs.readFile('design/seo-content-verification.json','utf8'));
const output=existsSync('dist/client/index.html')?'dist/client':'dist';
const criteria=['Local technical foundations','Intent and metadata clarity','Useful decision-making detail','Distinctiveness and contextual links','Evidence and demonstrated expertise'];
const labels={home:'Homepage',service:'Parent services',subservice:'Specialist services',growth:'Search strategy service',industry:'Industry pages','work-detail':'Project case studies',article:'Articles',services:'Service directory',industries:'Industry directory',work:'Work directory',about:'About',team:'Hire team',contact:'Contact',blog:'Blog directory',privacy:'Privacy',terms:'Terms'};
const make=(dimensions,reason,remaining)=>({dimensions,reason,remaining});
// Editorial judgments. These values are not inferred from word count or vendor scores.
function assess(p){
 const projectEvidence=p.links.some(link=>link.href.startsWith('/work/')); 
 if(['privacy','terms'].includes(p.type))return make(null,'Utility page; metadata is clearer and its informational purpose is preserved.','Keep the document accurate. Legal completeness and non-brand acquisition potential are not scored.');
 if(p.type==='subservice')return make(projectEvidence?[2,2,1.5,1.5,1.5]:[2,2,1.5,1.5,.5],p.service==='ai'?'Specific evaluation, permissions, exceptions and human-review guidance replace broad AI claims; contextual guide links support planning.':'The inherited parent body is replaced by distinct scope, deliverables, implementation decisions and specific FAQs. Duplicate process content and self-linked cards are removed.',projectEvidence?'Owner-confirmed project screens now support related workflows. Add exact delivery responsibilities and documented outcomes where supplied; a related screen does not establish a technology stack.':'Add relevant project implementation detail and query-led refinements once public. No unrelated project is used as technical proof.');
 if(p.type==='service')return make(projectEvidence?[2,2,1.5,1.5,1.5]:[2,2,1.5,1,.5],'The hub explains when the service fits, alternatives, delivery decisions and specialist options rather than relying on a slogan.',projectEvidence?'Related genuine project workflows now connect the offer with visual evidence. Exact project roles, stack and outcomes remain unconfirmed.':'Add relevant implementation detail and stronger differentiation. Shared hub process wording remains; demand by market is unverified.');
 if(p.type==='industry')return make(projectEvidence?[2,2,1.5,1.5,1.5]:[2,2,1.5,1.5,.5],'Sector-specific data ownership, workflows, integration constraints and exception handling replace generic industry copy; links lead to relevant services.','Use exact project scope and domain evidence where available. Owner-confirmed project screens do not establish regulatory credentials or every specialised workflow described on the page.');
 if(p.type==='work-detail')return make([2,2,1.5,2,1.5],'The owner confirms this is genuine project work. The case study now explains the brief, visible workflow decisions, project capabilities and captioned desktop/mobile screens, with project-specific structured data.','Exact responsibilities, live project URLs, implementation stack and measured outcomes were not supplied and are not invented. These would strengthen the case beyond the current screen-grounded account.');
 if(p.type==='article')return make(p.route.endsWith('seo-aeo-geo-where-to-start')?[2,2,1.5,1.5,.5]:[2,2,2,1.5,1],'Clearer search-oriented title, useful decision structure, a hypothetical worked example and service-specific links improve the reading-to-enquiry journey.','Related project case studies now supplement the planning examples where relevant. Original research, exact project outcomes and accountable expert contribution remain opportunities.');
 if(p.type==='growth')return make([2,2,1.5,1,.5],'The page now states its broader search-strategy purpose, differentiates page-level SEO and replaces unsupported traffic/project metrics with deliverables.','Add an approved audit example, documented implementation results and a genuine measurement baseline. Positioning remains broad.');
 const core={
  home:make([2,2,1.5,1,1],'The stable H1 describes software and AI automation. The directory copy is more accurate, and navigation reaches all current portfolio routes.','Provide substantiated business evidence and genuine project outcomes. The broad multi-service positioning still needs market validation.'),
  services:make([2,2,1.5,1,.5],'Directory guidance now explains how to choose between services and separates page-level SEO from broader search strategy.','Improve selection using real buyer questions and business priorities; this is primarily a navigation hub.'),
  industries:make([2,1.5,1,1,.5],'The directory explicitly describes industry software workflows and sets accurate expectations for its linked examples.','Add more useful sector-selection context if it serves actual buyers. Acquisition value chiefly lies in the detailed industry pages.'),
  work:make([2,2,1.5,1.5,1],'The directory presents owner-confirmed project case studies with descriptive titles and links to deeper workflow accounts.','Add live project references and exact delivery scope when available. Project authenticity is owner-confirmed, not independently audited.'),
  about:make([2,1.5,1,1.5,1],'Founder identity is preserved and delivery, ownership and handover practices are more concrete.','Add verified team credentials, business details and relevant experience. Some values-led language remains general.'),
  team:make([2,2,1.5,1,.5],'The title and content describe roles, engagement models, onboarding, access and review responsibilities.','Provide genuine role profiles, examples and confirmed availability when appropriate; staffing capability is not independently established by copy.'),
  contact:make([2,2,1.5,1,1],'The page asks for useful workflow context and explains early-stage and focused engagements; the route supports conversion.','Verify the public submission and reply experience after deployment. Score is for purpose fit, not expected non-brand traffic.'),
  blog:make([2,1.5,1.5,1,.5],'The hub describes its planning guides clearly and links to the improved articles through a crawlable directory.','Organise future guides around validated buyer questions. Most organic acquisition should be assessed at article level.')
 };
 if(!core[p.type])throw Error('Missing assessment for '+p.route);
 return core[p.type];
}
const clean=x=>x.replace(/\s+/g,' ').trim();
const pages=[];
for(const route of routes){
 const info=routeInfo(route),old=baseline.pages.find(p=>p.route===route);
 if(!old)throw Error('No baseline for '+route);
 const doc=new JSDOM(await fs.readFile(output+(route==='/'?'':route)+'/index.html','utf8'));
 const d=doc.window.document,main=d.querySelector('main');
 const title=d.title,description=d.querySelector('meta[name="description"]')?.content;
 if(title!==metadata(route).title||description!==metadata(route).description)throw Error('Stale build at '+route);
 const headings=[...main.querySelectorAll('h1,h2,h3')].map(h=>({level:h.tagName,text:clean(h.textContent)}));
 const links=[...main.querySelectorAll('a[href]')].map(a=>({text:clean(a.textContent),href:a.getAttribute('href')}));
 const images=main.querySelectorAll('img').length;
 main.querySelectorAll('svg,script,style').forEach(x=>x.remove());
 const text=clean(main.textContent);
 const page={route,type:info.type,service:info.service?.slug,title,description,h1:headings.filter(h=>h.level==='H1').map(h=>h.text),headings,links,text,words:text.split(/\s+/).length,images,canonical:d.querySelector('link[rel="canonical"]')?.href,localRobots:d.querySelector('meta[name="robots"]')?.content,before:{score:old.assessment.score,title:old.title,words:old.words,images:old.images},priority:old.assessment.priority};
 const assessment=assess(page);page.assessment={...assessment,score:assessment.dimensions?assessment.dimensions.reduce((a,b)=>a+b,0):null};
 page.delta=page.assessment.score===null?null:page.assessment.score-page.before.score;
 pages.push(page);doc.window.close();
}
let next=0;
await Promise.all(Array.from({length:6},async()=>{while(next<pages.length){const p=pages[next++],url='https://cubusify.com'+(p.route==='/'?'/':p.route+'/');try{const r=await fetch(url,{signal:AbortSignal.timeout(18000)});const html=await r.text(),dom=new JSDOM(html);p.live={url,status:r.status,finalUrl:r.url,title:dom.window.document.title,xRobotsTag:r.headers.get('x-robots-tag'),matchesLocalTitle:dom.window.document.title===p.title};dom.window.close();}catch(e){p.live={url,error:e.message};}}}));
const scored=pages.filter(p=>p.assessment.score!==null);
const mean=xs=>Math.round(xs.reduce((a,b)=>a+b,0)/xs.length*10)/10;
const groups=Object.entries(labels).map(([type,label])=>{const group=pages.filter(p=>p.type===type),s=group.filter(p=>p.assessment.score!==null);return {type,label,pages:group.length,before:s.length?mean(s.map(p=>p.before.score)):null,after:s.length?mean(s.map(p=>p.assessment.score)):null};});
const counts={pages:pages.length,scored:scored.length,utility:pages.length-scored.length,beforeMean:mean(scored.map(p=>p.before.score)),afterMean:mean(scored.map(p=>p.assessment.score)),atLeastSeven:scored.filter(p=>p.assessment.score>=7).length,liveStatuses:pages.reduce((m,p)=>(m[p.live.status??'error']=(m[p.live.status??'error']||0)+1,m),{}),matchingPublicTitles:pages.filter(p=>p.live.matchesLocalTitle).length};
let lighthouse=null;
try{lighthouse=JSON.parse(await fs.readFile('design/lighthouse-seo-summary.json','utf8'));}catch{}
const audit={lighthouse,date:reportDate,version:'Post-project-confirmation and image-SEO reassessment',domain:'cubusify.com',method:'Current built HTML checked against current source metadata; all canonical public routes requested again. Scores are editorial local content-readiness judgments, not Google/vendor ratings, measured rankings, search demand or traffic forecasts. Original scores are retained as recorded; explicit current criterion breakdowns explain the reassessment.',criteria:criteria.map(label=>({label,maximum:2})),counts,groups,verification:{uniqueTitles:new Set(pages.map(p=>p.title)).size,uniqueDescriptions:new Set(pages.map(p=>p.description)).size,existingImageAssetsPreserved:true,additionalRenderedImages:pages.reduce((n,p)=>n+p.images-p.before.images,0),maximumSiblingFiveWordJaccard:verification.maximumSiblingFiveWordJaccard,siblingPairs:verification.specialistComparisonCount,frontendChecks:'Passed in the implementation session',enquiryTests:'6 passed',interactionTests:'6 passed; 3 failures reproduce on original HEAD',browserVisuals:'Local Chrome mobile/desktop checks; see seo-browser-checks.json',coreWebVitals:'Local unthrottled LCP/CLS observations only; not real-user field data',searchConsole:'Not connected or verified',trafficAndRankings:'Not retrieved; Ahrefs plan insufficient and Semrush API units unavailable in the initial audit'},pages};
const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const n=x=>x===null?'Utility':Number(x).toFixed(1);
const grade=p=>p.assessment.score===null?'Utility':p.assessment.score>=8?'Strong content foundation':p.assessment.score>=7?'Good foundation':'Further improvement';
const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';
const csv='Page,Type,Before,Updated,Change,Priority,Live HTTP,Current title,Reason,Remaining work\n'+pages.map(p=>[p.route,p.type,p.before.score,p.assessment.score,p.delta,p.priority,p.live.status??p.live.error,p.title,p.assessment.reason,p.assessment.remaining].map(quote).join(',')).join('\n')+'\n';
const embedded=JSON.stringify({audit,csv}).replaceAll('<','\\u003c').replaceAll('\u2028','\\u2028').replaceAll('\u2029','\\u2029');
const rows=pages.map(p=>`<tr class="page" data-type="${esc(p.type)}" data-score="${p.assessment.score??'utility'}" data-priority="${esc(p.priority)}" data-search="${esc((p.route+' '+p.title+' '+p.assessment.remaining).toLowerCase())}"><td><code>${esc(p.route)}</code><small>${esc(labels[p.type])}</small><details class="evidence"><summary>Score breakdown &amp; page evidence</summary>${p.assessment.dimensions?`<dl>${criteria.map((c,i)=>`<dt>${esc(c)}</dt><dd>${n(p.assessment.dimensions[i])} / 2</dd>`).join('')}</dl>`:'<p>Utility page: not scored for organic acquisition.</p>'}<p><strong>Title:</strong> ${esc(p.title)}</p><p><strong>Description:</strong> ${esc(p.description)}</p><p><strong>H1:</strong> ${p.h1.map(esc).join(' / ')}</p><p><strong>Words:</strong> ${p.words} · <strong>Images:</strong> ${p.images} current placements of existing assets</p><p><strong>Canonical:</strong> ${esc(p.canonical)}</p><p><strong>Local robots:</strong> ${esc(p.localRobots)}</p><p><strong>Public title:</strong> ${esc(p.live.title||'(none returned)')}</p><details><summary>Headings</summary><ul>${p.headings.map(h=>`<li>${esc(h.level)} · ${esc(h.text)}</li>`).join('')}</ul></details><details><summary>Full current main content</summary><p>${esc(p.text)}</p></details><details><summary>Current internal and external links</summary><ul>${p.links.map(l=>`<li>${esc(l.text)} <code>${esc(l.href)}</code></li>`).join('')}</ul></details></details></td><td>${n(p.before.score)}</td><td><strong class="score ${p.assessment.score===null?'neutral':p.assessment.score>=7?'good':'amber'}">${n(p.assessment.score)}${p.assessment.score===null?'':' / 10'}</strong><small>${esc(grade(p))}</small></td><td>${p.delta===null?'—':(p.delta>0?'+':'')+p.delta.toFixed(1)}</td><td><strong>${esc(p.priority)}</strong><small>HTTP ${esc(p.live.status??'unknown')}${p.live.status===200&&!p.live.matchesLocalTitle?' · different public version':''}</small></td><td><p>${esc(p.assessment.reason)}</p><p><strong>Remaining:</strong> ${esc(p.assessment.remaining)}</p></td></tr>`).join('');
const summaryRows=groups.map(g=>`<tr><td>${esc(g.label)}</td><td>${g.pages}</td><td>${n(g.before)}</td><td><strong>${n(g.after)}</strong></td></tr>`).join('');
const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cubusify — Updated SEO Score Report — ${displayDate}</title><style>
:root{--ink:#14243e;--muted:#52647b;--line:#dce4ef;--blue:#175cd3}*{box-sizing:border-box}body{margin:0;background:#f3f6fb;color:var(--ink);font:15px/1.65 system-ui,-apple-system,"Segoe UI",sans-serif}header{background:#102340;color:white;padding:40px max(22px,calc((100vw - 1320px)/2))}h1{font-size:clamp(30px,4vw,46px);line-height:1.15;margin:12px 0}header p{max-width:920px;color:#d3e0f4}.eyebrow{font-size:12px;letter-spacing:.12em;color:#83c9ff;text-transform:uppercase}main{max-width:1370px;margin:auto;padding:24px 22px 60px}.panel{border:1px solid var(--line);border-radius:15px;background:white;padding:26px;margin-bottom:22px}h2{font-size:25px;line-height:1.3;margin:0 0 15px}h3{font-size:19px}p{margin:10px 0}.notice{background:#fff6ed;border-left:5px solid #c75a13}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:22px}.metric{background:white;border:1px solid var(--line);border-radius:13px;padding:20px}.metric strong{display:block;font-size:30px;line-height:1.3}.metric span,small,.note{color:var(--muted);font-size:12px}small{display:block;margin-top:6px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px;text-align:left}th{background:#edf3fc;color:#354d70}td,th{padding:14px;border-bottom:1px solid var(--line);vertical-align:top}.score{display:inline-block;white-space:nowrap;padding:4px 8px;border-radius:7px}.good{background:#e8f6ee;color:#14653d}.amber{background:#fff4d8;color:#815500}.neutral{background:#edf1f7;color:#43536b}code{font-size:12px;overflow-wrap:anywhere}details{margin-top:12px}summary{color:var(--blue);font-size:12px;font-weight:650;cursor:pointer}.evidence{max-width:650px;min-width:220px}dt{font-weight:650;margin-top:8px}dd{margin:0}li{margin:8px 0}.filters,.tools{display:flex;flex-wrap:wrap;gap:10px;margin:15px 0}input,select,button{font:inherit;color:var(--ink);background:white;border:1px solid #c5d1e1;border-radius:8px;padding:10px 12px}input{flex:1;min-width:220px}button{cursor:pointer}button:hover{background:#edf3fc}.sort{border:0;padding:0;background:none;font:inherit;font-weight:700;color:inherit}#pages-table{min-width:1100px}#pages-table th:nth-child(1){width:25%}#pages-table th:nth-child(2){width:6%}#pages-table th:nth-child(3){width:12%}#pages-table th:nth-child(4){width:6%}#pages-table th:nth-child(5){width:12%}a{color:var(--blue)}header a{color:#b6d7ff}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.raw{max-height:420px;overflow:auto;background:#f5f7fb;padding:16px}footer{font-size:12px;color:var(--muted)}[hidden]{display:none!important}:focus-visible{outline:3px solid #4b9eff;outline-offset:3px}@media(max-width:700px){main{padding:18px 12px}.panel{padding:20px 16px}.metrics{grid-template-columns:1fr 1fr}.metric{padding:15px}.metric strong{font-size:25px}}@media print{body{background:white;font-size:10pt}header{background:white;color:#14243e;padding:0}header p{color:#52647b}main{padding:0}.panel{border:0;padding:0}.filters,.tools,.evidence,#raw{display:none!important}.scroll{overflow:visible}#pages-table{min-width:0;font-size:8pt}th,td{padding:7px}tr{break-inside:avoid}thead{display:table-header-group}.page[hidden]{display:table-row!important}}
</style></head><body><header><div class="eyebrow">Cubusify / Post-update reassessment / ${displayDate}</div><h1>Updated SEO score report</h1><p>Before-and-after editorial ratings for all 84 current pages, with criterion breakdowns, remaining improvements and a fresh public-availability check.</p><a href="#ratings">View all page scores ↓</a></header><main>
<section class="panel notice"><h2>Content readiness improved. Public availability remains separate.</h2><p>${counts.liveStatuses[404]??0} of ${counts.pages} portfolio URLs returned HTTP 404 in this fresh check. ${counts.matchingPublicTitles} public page titles match the updated local titles. The homepage ${pages.find(p=>p.route==='/').live.status===200?'returns 200 but serves a different version':'could not be confirmed as the updated version'}.</p><p>These scores assess the built local portfolio. They do not establish Google indexing, rankings, clicks or traffic growth. Publishing and measurement remain necessary.</p></section>
<div class="metrics"><div class="metric"><strong>${n(counts.beforeMean)} → ${n(counts.afterMean)}</strong><span>Mean readiness / 10 · same ${counts.scored} scored pages</span></div><div class="metric"><strong>${counts.atLeastSeven} / ${counts.scored}</strong><span>Pages rated 7 or higher</span></div><div class="metric"><strong>84 / 84</strong><span>Unique titles and descriptions</span></div><div class="metric"><strong>${(verification.maximumSiblingFiveWordJaccard.similarity*100).toFixed(1)}%</strong><span>Highest current sibling phrase similarity</span></div></div>
<section class="panel"><h2>Measured technical SEO</h2>${lighthouse?'<p><strong>'+lighthouse.minimumScore+'/100 minimum Lighthouse SEO score across '+lighthouse.pages.length+' representative local pages.</strong> Tests recorded '+esc(lighthouse.date)+'; this report refreshed '+esc(reportDate)+'. These are measured checklist results from Lighthouse '+esc(lighthouse.version)+', separate from the editorial ratings below.</p><div class="scroll"><table><thead><tr><th>Audited local page</th><th>SEO score</th><th>Report</th></tr></thead><tbody>'+lighthouse.pages.map(p=>'<tr><td>'+esc(p.route)+'</td><td>'+p.score+'/100</td><td><a href="'+esc(p.report)+'">Open Lighthouse report</a></td></tr>').join('')+'</tbody></table></div>':'<p>Lighthouse summary not yet available.</p>'}<p>This meets a 95/100 technical-checklist target on audited pages if the minimum above is at least 95. It does not establish a universal 9.5/10 content grade, live indexing, authority or organic traffic. All 84 routes also pass the local metadata, image, schema and link checks.</p></section><section class="panel"><h2>How the ratings were assessed</h2><p>Each page receives up to two points in five areas: local technical foundations; intent and metadata clarity; useful decision-making detail; distinctiveness and contextual links; and evidence of expertise. Ratings are subjective editorial judgments in half-point increments. Word count is descriptive only.</p><p>The original scores are preserved as recorded. The new explicit breakdown makes the reassessment easier to inspect. A score increase records an editorial assessment of the content changes; it is not a measured SEO performance improvement.</p><p><strong>8–10:</strong> strong content foundation. <strong>7–7.5:</strong> good foundation with evidence gaps. <strong>Below 7:</strong> further improvement. Privacy and Terms are unscored utility documents. Contact is scored for conversion purpose, not expected non-brand acquisition.</p><p>Technical points cover local HTML, metadata, schema and links. They exclude live deployment, measured Core Web Vitals and Google indexing. Project authenticity is confirmed by the business owner. Evidence points recognise the supplied project screens and their detailed explanations. Exact project roles, implementation stacks, external references and quantified results remain unconfirmed.</p></section>
<section class="panel"><h2>Scores by page group</h2><div class="scroll"><table><thead><tr><th scope="col">Group</th><th scope="col">Pages</th><th scope="col">Before / 10</th><th scope="col">Updated / 10</th></tr></thead><tbody>${summaryRows}</tbody></table></div><h3>Strongest content foundations</h3><ul><li>Ecommerce, AI and MVP guides: <strong>8.5/10</strong>. The guides now connect planning detail with owner-confirmed project work; broader research and measured project outcomes remain opportunities.</li><li>Specialist services: <strong>7.5?8.5/10</strong>. Distinct scope and FAQs are supplemented with related project screens where the subject fits. No unrelated project is used to claim a technical implementation.</li><li>Project case studies: <strong>9.0/10</strong>. Detailed screen walkthroughs, captions and structured data now support owner-confirmed genuine project work. Exact roles and measured outcomes remain unconfirmed.</li></ul><h3>Where further work matters</h3><ol><li><strong>Publish the intended portfolio and verify it publicly.</strong> Readiness improvements cannot make missing routes attract search traffic.</li><li><strong>Add real proof to priority service pages.</strong> Approved project narratives, documented decisions and observed results will add more than further generic paragraphs.</li><li><strong>Document exact project delivery.</strong> Add public project references, responsibilities and substantiated outcomes when available. Screens establish visible workflows but do not prove an unconfirmed backend or business result.</li><li><strong>Measure demand and qualified enquiries.</strong> Validate target-market queries, indexing and conversion before choosing the next content batch.</li></ol></section>
<section class="panel" id="ratings"><h2>All updated page scores</h2><p>Open page evidence for the five-part score breakdown, current content, headings and links. P1/P2/P3 retain the initial commercial-priority shortlist; they are not measured keyword opportunity scores. Public deployment is a separate site-wide prerequisite.</p><div class="filters"><input id="search" type="search" aria-label="Search pages" placeholder="Search URL, title or remaining work…"><select id="type" aria-label="Page group"><option value="">All groups</option>${Object.entries(labels).map(([key,label])=>`<option value="${esc(key)}">${esc(label)}</option>`).join('')}</select><select id="score-filter" aria-label="Current rating"><option value="">All scores</option><option value="strong">8 or higher</option><option value="good">7–7.5</option><option value="improve">Below 7</option><option value="utility">Utility</option></select><select id="priority" aria-label="Priority"><option value="">All priorities</option><option>P1</option><option>P2</option><option>P3</option></select></div><p class="note" id="count" role="status">Showing 84 pages</p><div class="scroll"><table id="pages-table"><thead><tr><th scope="col"><button class="sort" data-sort="route">Page ↕</button></th><th scope="col">Before</th><th scope="col"><button class="sort" data-sort="score">Updated ↕</button></th><th scope="col">Change</th><th scope="col">Priority / public HTTP</th><th scope="col">Assessment and remaining improvements</th></tr></thead><tbody>${rows}</tbody></table></div><noscript>All page scores are visible without JavaScript. Filters, sorting and downloads require JavaScript.</noscript></section>
<section class="panel"><h2>Verification and limitations</h2><p>84 unique titles; 84 unique descriptions; existing image files preserved and additional uses of the same project images added. Local checks passed for links, metadata, structured data, sitemap coverage and reachability. The implementation checks verified existing image hashes.</p><p>Sibling text similarity is a five-word Jaccard diagnostic: the initially repetitive non-AI pages had nearest matches of 86.9–91.8%; the maximum among current within-family specialist pairs is ${(verification.maximumSiblingFiveWordJaccard.similarity*100).toFixed(1)}%. This is not a Google duplication or penalty score.</p><p>Six enquiry tests passed. Six interaction tests passed; three failures reproduced on the original HEAD. Local mobile and desktop Chrome smoke checks were run. Field Core Web Vitals and full device interaction QA remain unverified. Search Console, traffic, rankings, keyword volumes and backlinks were not available. Ahrefs and Semrush account limits prevented the initial connector research. No numerical traffic uplift is claimed.</p><div class="tools"><button id="download-csv">Download ratings CSV</button><button id="download-json">Download complete evidence JSON</button><button id="print">Print / Save PDF</button></div><details id="raw"><summary>Complete embedded report data</summary><pre class="raw">${esc(JSON.stringify(audit,null,2))}</pre></details></section><footer>Self-contained report. No external fonts, libraries or runtime data requests. Public response checks are a dated snapshot; they do not prove search-engine indexing. Report generation does not change application code or deploy the website.</footer></main>
<script id="data" type="application/json">${embedded}</script><script>
const data=JSON.parse(document.getElementById('data').textContent);const rows=[...document.querySelectorAll('tr.page')];const controls=['search','type','score-filter','priority'].map(id=>document.getElementById(id));function filter(){const [q,t,s,p]=controls.map(x=>x.value.toLowerCase().trim());let count=0;rows.forEach(row=>{const d=row.dataset,n=Number(d.score);const visible=(!q||d.search.includes(q))&&(!t||d.type===t)&&(!p||d.priority.toLowerCase()===p)&&(!s||(s==='utility'?d.score==='utility':d.score!=='utility'&&(s==='strong'?n>=8:s==='good'?n>=7&&n<8:n<7)));row.hidden=!visible;if(visible)count++;});document.getElementById('count').textContent='Showing '+count+' of '+rows.length+' pages';}controls.forEach(x=>x.addEventListener('input',filter));let key='',direction=1;document.querySelectorAll('[data-sort]').forEach(button=>button.addEventListener('click',()=>{direction=key===button.dataset.sort?-direction:1;key=button.dataset.sort;document.querySelectorAll('#pages-table th').forEach(th=>th.removeAttribute('aria-sort'));button.parentElement.setAttribute('aria-sort',direction===1?'ascending':'descending');const value=row=>key==='route'?row.querySelector('code').textContent:row.dataset.score==='utility'?-1:Number(row.dataset.score);rows.sort((a,b)=>{const x=value(a),y=value(b);return (typeof x==='number'?x-y:x.localeCompare(y))*direction;}).forEach(row=>document.querySelector('#pages-table tbody').appendChild(row));}));function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}document.getElementById('download-csv').addEventListener('click',()=>download(data.csv,'cubusify-updated-seo-scores.csv','text/csv;charset=utf-8'));document.getElementById('download-json').addEventListener('click',()=>download(JSON.stringify(data.audit,null,2),'cubusify-updated-seo-scores.json','application/json'));document.getElementById('print').addEventListener('click',()=>window.print());
</script></body></html>`;
